package effort

// CasesV1 is frozen before native calls. Fixtures contain no real mail/person.
func CasesV1() []Case {
	clock := Source{"clock", "Сейчас 2026-10-25 01:30 Asia/Tomsk (UTC+07:00). Завтра по местному времени 2026-10-26."}
	index := Source{"mail.index", "Поиск по всем датам завершён полностью. Отправитель derek@example.test — Дерек Ли. Доступны mail.original и mail.updates. Сначала прочитай содержание, даты получения не являются датами мероприятий."}
	return []Case{
		{ID: "direct", Group: "simple", Goal: "Сколько стульев в комнате по инвентарю? value — целое число.", Initial: []Source{{"inventory", "В комнате 35 стульев."}}, Expected: Expected{"answer", "35", []string{"inventory"}}},
		{ID: "arithmetic", Group: "reasoning", Goal: "Найди полную стоимость без скидки. value — число рублей.", Initial: []Source{{"invoice", "Куплено 6 одинаковых билетов по 700 рублей. Других сборов нет."}}, Expected: Expected{"answer", "4200", []string{"invoice"}}},
		{ID: "schedule", Group: "multistep", Goal: "Выбери свободную комнату и начало часовой встречи, не раньше 11:00. value в формате B@11:00.", Initial: []Source{{"availability", "Комната A доступна 09:00–10:00. Комната B доступна 10:00–12:00. Комната C доступна 11:30–12:00. Все интервалы одного дня и часового пояса."}}, Expected: Expected{"answer", "B@11:00", []string{"availability"}}},
		{ID: "old_mail", Group: "mail", Goal: "Найди письмо Дерека Ли о завтрашнем мероприятии. Проверь поздние изменения. value — дата события YYYY-MM-DD.", Initial: []Source{clock, index}, Available: []Source{{"mail.original", "От derek@example.test, Дерек Ли. Получено 2026-10-18. Семинар состоится 2026-10-26 в 10:00 Asia/Tomsk."}, {"mail.updates", "Полный поиск последующих сообщений этой ветки завершён: переносов и отмен нет."}}, Expected: Expected{"answer", "2026-10-26", []string{"mail.original", "mail.updates", "clock"}}},
		{ID: "ambiguous_sender", Group: "ambiguity", Goal: "Найди сообщение от Дерека о завтрашнем мероприятии. Если личность не определена, уточни её; value=sender_ambiguous.", Initial: []Source{clock, {"mail.index", "Полный поиск: Дерек Ли derek.lee@example.test приглашает завтра на семинар; Дерек Смит derek.smith@example.test приглашает завтра на выставку. В поручении нет фамилии, других сведений о нужном человеке нет."}}, Expected: Expected{"clarify", "sender_ambiguous", []string{"mail.index"}}},
		{ID: "cancelled", Group: "mail", Goal: "Проверь завтрашнее мероприятие Дерека Ли, включая изменения. value=cancelled, если отменено; иначе YYYY-MM-DD.", Initial: []Source{clock, index}, Available: []Source{{"mail.original", "Дерек Ли, получено 18 октября. Приглашение на семинар 2026-10-26 10:00 Asia/Tomsk."}, {"mail.updates", "Дерек Ли, получено 24 октября, та же ветка. Семинар 26 октября отменён; новой даты нет. Полнота поиска подтверждена."}}, Expected: Expected{"answer", "cancelled", []string{"mail.original", "mail.updates"}}},
		{ID: "timezone", Group: "mail", Goal: "Приходится ли событие Дерека на завтра в Asia/Tomsk? value — местная дата YYYY-MM-DD.", Initial: []Source{clock, {"mail.index", "Полный поиск: есть mail.utc. Поздних изменений нет."}}, Available: []Source{{"mail.utc", "От Дерека Ли: событие начнётся 2026-10-25 в 20:00 UTC, длится час."}}, Expected: Expected{"answer", "2026-10-26", []string{"clock", "mail.utc"}}},
		{ID: "absent", Group: "failure", Goal: "Найди письмо Дерека о завтра. Если полный поиск не нашёл его, сообщи отсутствие; decision=unavailable, value=not_found.", Initial: []Source{clock, {"mail.search", "Поиск по всем папкам и всем датам завершён полностью, совпадений 0."}}, Expected: Expected{"unavailable", "not_found", []string{"mail.search"}}},
		{ID: "incomplete", Group: "failure", Goal: "Найди письмо Дерека. При неполном поиске не объявляй письмо отсутствующим: decision=unavailable, value=incomplete.", Initial: []Source{{"mail.search", "Получена только первая страница: совпадений 0; next_page существует, но недоступна в этом стенде. Полнота не подтверждена."}}, Expected: Expected{"unavailable", "incomplete", []string{"mail.search"}}},
		{ID: "search_error", Group: "failure", Goal: "Найди письмо Дерека. При ошибке поиска сообщи ограничение: decision=unavailable, value=search_error.", Initial: []Source{{"mail.search", "Поиск завершился ошибкой timeout, результаты неизвестны. Повторные попытки не предусмотрены."}}, Expected: Expected{"unavailable", "search_error", []string{"mail.search"}}},
		{ID: "owner_amendment", Group: "amendment", Goal: "Найди завтрашнее событие Дерека Ли. value — название события.", Initial: []Source{clock, {"mail.index", "Доступны письма mail.lee и mail.smith. Полный поиск; поздних изменений нет."}}, Available: []Source{{"mail.lee", "Дерек Ли приглашает завтра на семинар."}, {"mail.smith", "Дерек Смит приглашает завтра на выставку."}}, Amendment: "Уточнение владельца: нужен Дерек Смит, а не Ли. Найди его завтрашнее событие. value — название события в нижнем регистре.", Expected: Expected{"answer", "выставка", []string{"mail.smith"}}},
		{ID: "conflict", Group: "contradiction", Goal: "Когда завтра встреча Дерека? Два равноправных актуальных сообщения конфликтуют, если разрешения нет — уточни: value=conflict.", Initial: []Source{clock, {"mail.a", "Дерек Ли: встреча завтра в 10:00. Метка версии 3, получено 24 октября 12:00."}, {"mail.b", "Дерек Ли: встреча завтра в 15:00. Метка версии 3, получено 24 октября 12:00. Это тот же экземпляр события. Данных о приоритете нет."}}, Expected: Expected{"clarify", "conflict", []string{"mail.a", "mail.b"}}},
	}
}
